(function () {
  'use strict';
  var root = document.documentElement;
  var KEY = 'sky-bilingual-v1';
  var state = { view: 'both', level: 'all', fs: 17, theme: 'auto' };

  // restore preferences (safe if storage is unavailable)
  try {
    var saved = JSON.parse(localStorage.getItem(KEY) || '{}');
    for (var k in state) { if (saved.hasOwnProperty(k)) state[k] = saved[k]; }
  } catch (e) { /* ignore */ }

  function persist() {
    try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) { /* ignore */ }
  }

  function syncButtons() {
    document.querySelectorAll('[data-view]').forEach(function (b) {
      b.setAttribute('aria-pressed', String(b.dataset.view === state.view));
    });
    document.querySelectorAll('[data-level]').forEach(function (b) {
      if (b.tagName !== 'BUTTON') return;
      b.setAttribute('aria-pressed', String(b.dataset.level === state.level));
    });
    var t = document.getElementById('theme');
    if (t) t.textContent = ({ auto: 'Theme: auto', light: 'Theme: light', dark: 'Theme: dark' })[state.theme];
  }

  function apply() {
    root.dataset.view = state.view;
    root.dataset.level = state.level;
    root.style.setProperty('--fs', state.fs + 'px');
    if (state.theme === 'auto') root.removeAttribute('data-theme');
    else root.dataset.theme = state.theme;
    document.title = (state.level === 'all' ? '' : 'Level ' + state.level + ' · ')
      + 'Why Is the Sky Blue? · 天空为什么是蓝色的？';
    syncButtons();
    persist();
  }

  function setView(v) { state.view = v; apply(); }
  function setLevel(l) {
    state.level = l; apply();
    if (l !== 'all') {
      var s = document.querySelector('.level[data-level="' + l + '"]');
      if (s) window.scrollTo({ top: Math.max(0, s.offsetTop - 120), behavior: 'smooth' });
    } else {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }

  document.querySelectorAll('button[data-view]').forEach(function (b) {
    b.addEventListener('click', function () { setView(b.dataset.view); });
  });
  document.querySelectorAll('button[data-level]').forEach(function (b) {
    b.addEventListener('click', function () { setLevel(b.dataset.level); });
  });

  var FS_MIN = 13, FS_MAX = 24;
  function bumpFS(delta) {
    state.fs = Math.min(FS_MAX, Math.max(FS_MIN, Math.round((state.fs + delta) * 2) / 2));
    apply();
  }
  document.getElementById('fs-down').addEventListener('click', function () { bumpFS(-1); });
  document.getElementById('fs-up').addEventListener('click', function () { bumpFS(1); });

  document.getElementById('theme').addEventListener('click', function () {
    state.theme = state.theme === 'auto' ? 'light' : state.theme === 'light' ? 'dark' : 'auto';
    apply();
  });
  document.getElementById('print').addEventListener('click', function () { window.print(); });

  // keyboard shortcuts (ignored while typing in a field)
  document.addEventListener('keydown', function (e) {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    var t = e.target;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
    var k = e.key;
    if (k === '1') setLevel('1');
    else if (k === '2') setLevel('2');
    else if (k === '3') setLevel('3');
    else if (k === '0') setLevel('all');
    else if (k === 'e' || k === 'E') setView('en');
    else if (k === 'c' || k === 'C') setView('zh');
    else if (k === 'b' || k === 'B') setView('both');
    else if (k === 'a') bumpFS(e.shiftKey ? -1 : 1);
    else if (k === 'p' || k === 'P') { e.preventDefault(); window.print(); }
    else if (k === 'Escape') setLevel('all');
  });

  // scroll progress
  var bar = document.getElementById('progress');
  var ticking = false;
  function onScroll() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(function () {
      var h = root.scrollHeight - root.clientHeight;
      bar.style.width = (h > 0 ? Math.min(100, (root.scrollTop || document.body.scrollTop) / h * 100) : 0) + '%';
      ticking = false;
    });
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll);
  onScroll();

  apply();
})();
</script>
</body>
</html>
