import re,html
def htext(f):
    s=open(f,encoding='utf-8').read()
    s=re.sub(r'<(script|style)[^>]*>.*?</\1>','',s,flags=re.S)
    s=re.sub(r'<[^>]+>',' ',s); s=html.unescape(s)
