H=htext('index.html')

def norm(t):
    t=re.sub(r'\$[^$]*\$','§',t)          # math -> sentinel
    t=re.sub(r'\*\*|\*|`','',t)
    t=re.sub(r'^\d+\.\s*','',t); t=re.sub(r'^[-*]\s*','',t)
    t=re.sub(r'[|]',' ',t)
    t=re.sub(r'§+','§',t)
    # split on the sentinel: math regions are intentionally not compared
    return [c for c in t.split('§')]

def check(md,name):
    bad=[]
    for line in open(md,encoding='utf-8'):
        l=line.strip()
        if not l or l.startswith(('---','$$','#')): continue
        if l.startswith('|'):   # table row: compare cell contents
            cells=[c.strip() for c in l.strip('|').split('|')]
            for c in cells:
