            p=re.sub(r'\s+','',piece)
            if len(p)<14: continue
            if p not in H: bad.append((l,piece[:90]))
    print(f'=== {name}: {len(bad)} unmatched fragments ===')
    for l,f in bad[:20]: print(' *',f)
