{"path": "earth.html", "content": "<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>طبقات الأرض — عرض تعليمي</title>
<meta name="description" content="عرض بصري مبسّط وذاتي الاكتفاء عن طبقات الأرض: القشرة والوشاح واللب الخارجي واللب الداخلي.">
<meta name="author" content="Jennifer Robins">
<style>
/* =========================================================================
   طبقات الأرض — عرض تعليمي (Earth's geological layers)
   Single file, Arabic RTL. No external CSS, JS, fonts, or images.
   All diagrams are inline SVG with coordinates computed from real radii.
   ========================================================================= */

:root{
  --sans:"Segoe UI","Dubai","Noto Naskh Arabic","Noto Sans Arabic","Geeza Pro",
         "Al Bayan","Segoe UI Arabic",Tahoma,"Helvetica Neue",Arial,sans-serif;
  --num:"Segoe UI",Tahoma,Geneva,Verdana,sans-serif;

  --bg:#f6f2ec; --surface:#fffdfa; --surface-2:#faf5ee;
  --ink:#241b13; --muted:#6f6156; --line:#e6dccc; --line-2:#d5c5ae;
  --accent:#9c3f1b; --accent-soft:#f8ebe3;

  --crust:#b98a5e; --mantle:#c9532b; --outer:#e5943a; --inner:#f7d154;
  --deep:#3f2a1c;
  --shadow:0 1px 2px rgba(80,55,30,.07), 0 12px 34px -20px rgba(80,55,30,.45);
  --fs:18px;
}
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]){
    --bg:#141009; --surface:#1d1710; --surface-2:#241c14;
    --ink:#f3ece3; --muted:#ab9b8b; --line:#382c1f; --line-2:#4b3a28;
    --accent:#ef8f5e; --accent-soft:#2b1d14;
    --shadow:0 1px 2px rgba(0,0,0,.5), 0 14px 36px -20px rgba(0,0,0,.8);
  }
}
:root[data-theme="dark"]{
  --bg:#141009; --surface:#1d1710; --surface-2:#241c14;
  --ink:#f3ece3; --muted:#ab9b8b; --line:#382c1f; --line-2:#4b3a28;
  --accent:#ef8f5e; --accent-soft:#2b1d14;
  --shadow:0 1px 2px rgba(0,0,0,.5), 0 14px 36px -20px rgba(0,0,0,.8);
}

*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  font-family:var(--sans); font-size:var(--fs); line-height:1.85;
  color:var(--ink); background:var(--bg);
  -webkit-font-smoothing:antialiased; text-rendering:optimizeLegibility;
}
/* numbers & Latin tokens keep LTR order inside the RTL flow */
.n{unicode-bidi:isolate; direction:ltr; font-family:var(--num);
   font-variant-numeric:tabular-nums; white-space:nowrap; display:inline-block}
.lat{unicode-bidi:isolate; font-family:var(--num)}
[hidden]{display:none !important}

/* ---------- toolbar ---------- */
#bar{
  position:sticky; top:0; z-index:40;
  background:var(--surface); background:color-mix(in srgb,var(--surface) 88%,transparent);
  backdrop-filter:saturate(1.3) blur(10px);
  border-bottom:1px solid var(--line);
}
#bar .in{
  max-width:1180px; margin:0 auto; padding:.5rem clamp(.9rem,3vw,1.6rem);
  display:flex; align-items:center; gap:.55rem .7rem; flex-wrap:wrap;
}
.brand{display:flex; align-items:center; gap:.5rem; margin-inline-end:auto}
.brand .globe{width:1.05rem;height:1.05rem;border-radius:50%;flex:none;
  background:radial-gradient(circle at 68% 32%, var(--inner) 0 18%, var(--outer) 18% 42%, var(--mantle) 42% 78%, var(--crust) 78%);}
.brand b{font-size:.95rem}
.brand small{color:var(--muted); font-size:.75rem}
.grp{display:flex; align-items:center; gap:.25rem; padding:.18rem;
  background:var(--surface-2); border:1px solid var(--line); border-radius:999px}
button{
  font:inherit; font-size:.82rem; font-weight:700; color:var(--muted);
  background:transparent; border:0; border-radius:999px; padding:.32rem .72rem;
  cursor:pointer; display:inline-flex; align-items:center; gap:.35rem; white-space:nowrap;
}
button:hover{background:var(--accent-soft); color:var(--accent)}
button:focus-visible{outline:2px solid var(--accent); outline-offset:2px}
button:disabled{opacity:.35; cursor:default; background:transparent; color:var(--muted)}
.chev{width:.5rem;height:.5rem;border-inline-start:2px solid currentColor;border-block-start:2px solid currentColor;display:inline-block}
.chev.next{transform:rotate(-45deg)}   /* points left  → forward in RTL  */
.chev.prev{transform:rotate(135deg)}   /* points right → backward in RTL */
#counter{font-size:.78rem;color:var(--muted); font-family:var(--num); unicode-bidi:isolate; padding-inline:.4rem}
#progress{position:fixed; inset-block-start:0; inset-inline-start:0; height:3px; width:0;
  background:linear-gradient(to left,var(--mantle),var(--outer),var(--inner)); z-index:50}

/* ---------- deck ---------- */
#deck{max-width:1180px; margin:0 auto; padding:clamp(1rem,3vw,2.2rem) clamp(.9rem,3vw,1.6rem) 5.5rem}
.slide{animation:in .32s ease both}
@keyframes in{from{opacity:0; transform:translateY(8px)} to{opacity:1; transform:none}}
@media (prefers-reduced-motion:reduce){ .slide{animation:none} html{scroll-behavior:auto} }

.eyebrow{font-size:.74rem; font-weight:800; letter-spacing:.06em; color:var(--accent);
  text-transform:none; margin:0 0 .3rem}
h1{font-size:clamp(2.1rem,6vw,3.4rem); line-height:1.25; margin:0 0 .4rem; letter-spacing:-.01em}
h2{font-size:clamp(1.35rem,3.4vw,2rem); line-height:1.4; margin:0 0 .9rem; letter-spacing:-.01em}
h3{font-size:1.02rem; margin:1.1rem 0 .45rem}
p{margin:.55rem 0}
.lead{font-size:1.06rem; color:var(--muted); max-width:62ch}
.lede{color:var(--muted); max-width:64ch}

.card{background:var(--surface); border:1px solid var(--line); border-radius:16px;
  padding:1.15rem 1.3rem; box-shadow:var(--shadow)}
.grid{display:grid; gap:1.1rem}
.g-2{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
.g-side{grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr); align-items:start}
@media (max-width:860px){ .g-2,.g-side{grid-template-columns:minmax(0,1fr)} }

ul.tick{margin:.5rem 0; padding:0; list-style:none}
ul.tick li{position:relative; padding-inline-start:1.5rem; margin:.42rem 0}
ul.tick li::before{content:""; position:absolute; inset-inline-start:0; inset-block-start:.72em;
  width:.52rem; height:.52rem; border-radius:50%; background:var(--accent)}
strong{font-weight:800}
.hl{background:linear-gradient(transparent 62%, var(--accent-soft) 62%); border-radius:2px}

/* stat tiles */
.stats{display:flex; flex-wrap:wrap; gap:.6rem; margin:.9rem 0 0; padding:0; list-style:none}
.stats li{background:var(--surface); border:1px solid var(--line); border-radius:12px;
  padding:.5rem .8rem; font-size:.82rem; color:var(--muted); box-shadow:var(--shadow)}
.stats b{display:block; font-size:1.06rem; color:var(--ink); font-family:var(--num); unicode-bidi:isolate}

/* proportional depth bar (by radius, surface at the right in RTL) */
.depthbar{display:flex; height:2.4rem; border-radius:10px; overflow:hidden; border:1px solid var(--line-2)}
.depthbar span{display:flex; align-items:center; justify-content:center; font-size:.7rem;
  font-weight:700; color:#fff; text-shadow:0 1px 2px rgba(0,0,0,.35); min-width:14px}
.d-crust{flex:0 0 auto; width:.55%; background:var(--crust)}
.d-mantle{flex:0 0 auto; width:44.8%; background:var(--mantle)}
.d-outer{flex:0 0 auto; width:35.5%; background:var(--outer)}
.d-inner{flex:0 0 auto; width:19.2%; background:var(--inner); color:#4a3306; text-shadow:none}
.scale{display:flex; justify-content:space-between; font-family:var(--num); font-size:.7rem;
  color:var(--muted); margin-top:.3rem; unicode-bidi:isolate; direction:ltr}

/* interactive layer legend */
.legend{display:grid; gap:.5rem; margin:0; padding:0; list-style:none}
.legend button{width:100%; justify-content:flex-start; border-radius:12px; padding:.55rem .7rem;
  border:1px solid var(--line); background:var(--surface-2); font-weight:700; color:var(--ink);
  font-size:.9rem; text-align:start}
.legend button:hover{background:var(--accent-soft)}
.legend button[aria-pressed="true"]{border-color:var(--accent); background:var(--accent-soft); color:var(--accent)}
.legend .sw{width:.85rem;height:.85rem;border-radius:4px;flex:none;border:1px solid rgba(0,0,0,.18)}
#panel{font-size:.92rem}
#panel dl{display:grid; grid-template-columns:auto minmax(0,1fr); gap:.25rem .8rem; margin:.4rem 0 0}
#panel dt{color:var(--muted); font-size:.82rem; white-space:nowrap}
#panel dd{margin:0; font-weight:600}
#panel h3{margin-top:0}

/* tables */
table{width:100%; border-collapse:collapse; font-size:.86rem; margin:.6rem 0}
caption{caption-side:top; text-align:start; color:var(--muted); font-size:.78rem; padding-block-end:.45rem}
th,td{border:1px solid var(--line); padding:.48rem .6rem; text-align:start; vertical-align:top}
thead th{background:var(--surface-2); font-size:.78rem; color:var(--muted); font-weight:800}
tbody tr:nth-child(even){background:color-mix(in srgb,var(--surface-2) 55%,transparent)}
td.n{text-align:start; font-variant-numeric:tabular-nums}
.dot-crust,.dot-mantle,.dot-outer,.dot-inner{display:inline-block;width:.7rem;height:.7rem;
  border-radius:3px;margin-inline-end:.4rem;vertical-align:-1px}

/* temperature bars (grow from the right in RTL) */
.bars{display:grid; gap:.45rem; margin:.7rem 0 0}
.bars .row{display:grid; grid-template-columns:8.5rem minmax(0,1fr) 4.6rem; align-items:center; gap:.5rem; font-size:.82rem}
.bars .track{height:.85rem; background:var(--surface-2); border:1px solid var(--line); border-radius:999px; overflow:hidden}
.bars .fill{height:100%; border-radius:999px}
.bars .val{font-family:var(--num); unicode-bidi:isolate; text-align:end; color:var(--muted); font-size:.78rem}
@media (max-width:520px){ .bars .row{grid-template-columns:6rem minmax(0,1fr) 4rem; font-size:.76rem} }

/* timeline */
.timeline{display:flex; gap:.6rem; flex-wrap:wrap; margin-top:.9rem; padding:0; list-style:none}
.timeline li{flex:1 1 10rem; background:var(--surface-2); border:1px solid var(--line);
  border-radius:12px; padding:.6rem .75rem; border-block-start:3px solid var(--accent)}
.timeline .yr{font-family:var(--num); font-weight:800; color:var(--accent); font-size:.9rem; unicode-bidi:isolate}
.timeline .who{font-weight:700; font-size:.86rem}
.timeline .what{font-size:.78rem; color:var(--muted); line-height:1.6}

/* figures */
figure{margin:0; background:var(--surface); border:1px solid var(--line); border-radius:16px;
  padding:.9rem; box-shadow:var(--shadow)}
figcaption{font-size:.75rem; color:var(--muted); margin-top:.55rem; line-height:1.6}
svg{display:block; width:100%; height:auto; max-height:60vh}
svg text{font-family:var(--sans); fill:var(--ink); direction:rtl}
svg text.num{font-family:var(--num); direction:ltr; unicode-bidi:isolate}
.lyr{cursor:pointer; transition:filter .18s, opacity .18s}
.lyr:hover{filter:brightness(1.12)}
.lyr.is-sel{stroke:#fff; stroke-width:3.5}
.callout{background:var(--accent-soft); border:1px solid color-mix(in srgb,var(--accent) 28%,transparent);
  border-radius:12px; padding:.7rem .9rem; font-size:.9rem}
.callout b{color:var(--accent)}

/* ---------- bottom nav ---------- */
#nav{position:fixed; inset-block-end:0; inset-inline:0; z-index:45;
  background:var(--surface); background:color-mix(in srgb,var(--surface) 90%,transparent);
  backdrop-filter:saturate(1.3) blur(10px); border-top:1px solid var(--line)}
#nav .in{max-width:1180px; margin:0 auto; padding:.5rem clamp(.9rem,3vw,1.6rem);
  display:flex; align-items:center; justify-content:center; gap:.8rem}
#dots{display:flex; gap:.35rem; flex-wrap:wrap; justify-content:center}
#dots button{width:.62rem;height:.62rem;padding:0;border-radius:50%;
  background:var(--line-2); border:0}
#dots button[aria-current="true"]{background:var(--accent); transform:scale(1.35)}
#dots button:hover{background:var(--accent)}

footer{max-width:1180px; margin:0 auto; padding:1.2rem clamp(.9rem,3vw,1.6rem) 6.5rem;
  color:var(--muted); font-size:.76rem; border-top:1px solid var(--line); line-height:1.8}
footer code{font-family:var(--num); background:var(--surface); border:1px solid var(--line);
  border-radius:5px; padding:.05rem .3rem}

@media print{
  #bar,#nav,#progress{display:none !important}
  body{background:#fff; color:#000; font-size:11pt}
  [hidden]{display:block !important}
  .slide{break-after:page; padding-block:.5rem}
  .card,figure{box-shadow:none; break-inside:avoid}
  footer{padding-block-end:1rem}
}
</style>
</head>
<body>

<div id="progress" role="presentation"></div>

<header id="bar">
  <div class="in">
    <div class="brand">
      <span class="globe" aria-hidden="true"></span>
      <b>طبقات الأرض</b>
      <small>عرض تعليمي</small>
    </div>
    <div class="grp">
      <button type="button" id="prev" aria-label="الشريحة السابقة"><span class="chev prev" aria-hidden="true"></span> السابق</button>
      <button type="button" id="next" aria-label="الشريحة التالية"> التالي <span class="chev next" aria-hidden="true"></span></button>
    </div>
    <span id="counter" aria-live="polite"></span>
    <div class="grp">
      <button type="button" id="fs">ملء الشاشة</button>
      <button type="button" id="print">طباعة</button>
    </div>
  </div>
</header>

<main id="deck">

  <!-- ═══════════ 1 · الغلاف ═══════════ -->
  <section class="slide" role="group" aria-label="شريحة الغلاف">
    <p class="eyebrow">علوم الأرض · البنية الداخلية</p>
    <h1>طبقات الأرض</h1>
    <p class="lead">من قشرةٍ رقيقةٍ لا تكاد تُذكر إلى قلبٍ حديديٍّ أشدُّ حرارةً من سطح الشمس —
      رحلةٌ إلى عمق <span class="n">6371</span> كيلومتراً تحت قدميك.</p>
    <ul class="stats">
      <li>عمر الأرض<b><span class="n">≈ 4.54</span> مليار سنة</b></li>
      <li>نصف القطر المتوسط<b><span class="n">6371</span> كم</b></li>
      <li>الكثافة الوسطية<b><span class="n">5.51</span> غ/سم³</b></li>
      <li>عدد الطبقات الرئيسة<b><span class="n">4</span></b></li>
    </ul>
    <figure style="margin-top:1.4rem">
      <div class="depthbar" aria-hidden="true">
        <span class="d-crust"></span><span class="d-mantle">الوشاح</span>
        <span class="d-outer">اللب الخارجي</span><span class="d-inner">اللب الداخلي</span>
      </div>
      <div class="scale"><span>المركز</span><span>5150</span><span>2890</span><span>35</span><span>السطح (0 كم)</span></div>
      <figcaption>توزّع الطبقات بحسب <strong>نصف القطر</strong> لا بحسب الحجم: القشرة تشغل <span class="n">0.55%</span> فقط من نصف قطر الأرض،
        لذا تظهر في هذا الشريط كخطٍّ رفيع جداً — وهي كذلك فعلاً.</figcaption>
    </figure>
    <p class="callout" style="margin-top:1rem">
      <b>كيف تتنقّل؟</b> استخدم الأزرار أعلاه، أو مفاتيح الأسهم <span class="lat">←</span> و<span class="lat">→</span>،
      أو النقاط في الأسفل. اضغط <span class="lat">Home</span> للعودة إلى البداية.
    </p>
  </section>

  <!-- ═══════════ 2 · نظرة عامة ═══════════ -->
  <section class="slide" role="group" aria-label="نظرة عامة على البنية">
    <p class="eyebrow">الشريحة ٢ · البنية</p>
    <h2>أربع طبقاتٍ في نظرةٍ واحدة</h2>
    <div class="grid g-side">
      <figure>
        <svg viewBox="0 0 420 420" role="img" aria-labelledby="ttl-sec">
          <title id="ttl-sec">مقطعٌ نصفيٌّ للأرض يبيّن القشرة والوشاح واللب الخارجي واللب الداخلي</title>
          <defs>
            <radialGradient id="gm" cx="50%" cy="45%" r="60%">
              <stop offset="0%" stop-color="#e2673a"/><stop offset="100%" stop-color="#9c3a18"/>
            </radialGradient>
            <radialGradient id="go" cx="50%" cy="45%" r="60%">
              <stop offset="0%" stop-color="#f2a745"/><stop offset="100%" stop-color="#cf7a1c"/>
            </radialGradient>
            <radialGradient id="gi" cx="50%" cy="45%" r="60%">
              <stop offset="0%" stop-color="#ffe58a"/><stop offset="100%" stop-color="#eec343"/>
            </radialGradient>
          </defs>
          <circle cx="210" cy="210" r="190" fill="#b98a5e" class="lyr" data-layer="crust" tabindex="0" role="button" aria-label="القشرة الأرضية"/>
          <circle cx="210" cy="210" r="186" fill="url(#gm)" class="lyr" data-layer="mantle" tabindex="0" role="button" aria-label="الوشاح"/>
          <circle cx="210" cy="210" r="103.81" fill="url(#go)" class="lyr" data-layer="outer" tabindex="0" role="button" aria-label="اللب الخارجي"/>
          <circle cx="210" cy="210" r="36.41" fill="url(#gi)" class="lyr" data-layer="inner" tabindex="0" role="button" aria-label="اللب الداخلي"/>
          <circle cx="210" cy="210" r="186" fill="none" stroke="rgba(255,255,255,.30)" stroke-width="1.2" stroke-dasharray="4 6"/>
          <circle cx="210" cy="210" r="103.81" fill="none" stroke="rgba(255,255,255,.45)" stroke-width="1.4"/>
          <circle cx="210" cy="210" r="36.41" fill="none" stroke="rgba(255,255,255,.6)" stroke-width="1.2"/>
        </svg>
        <figcaption>نصفّا قُطر الوشاح واللبّ مرسومان بنسبةٍ صحيحة
          (<span class="n">103.81</span> و<span class="n">36.41</span> من أصل <span class="n">190</span>)،
          بينما سُمِّكت القشرة عمداً لتبقى مرئية. انقر على أي طبقة — أو على القائمة المجاورة — لعرض بياناتها.</figcaption>
      </figure>
      <div>
        <ul class="legend">
          <li><button type="button" data-layer="crust" aria-pressed="false"><span class="sw" style="background:var(--crust)"></span>القشرة الأرضية</button></li>
          <li><button type="button" data-layer="mantle" aria-pressed="false"><span class="sw" style="background:var(--mantle)"></span>الوشاح</button></li>
          <li><button type="button" data-layer="outer" aria-pressed="false"><span class="sw" style="background:var(--outer)"></span>اللب الخارجي</button></li>
          <li><button type="button" data-layer="inner" aria-pressed="false"><span class="sw" style="background:var(--inner)"></span>اللب الداخلي</button></li>
        </ul>
        <div class="card" id="panel" style="margin-top:.9rem" aria-live="polite">
          <h3>اختر طبقة</h3>
          <p style="color:var(--muted);font-size:.88rem;margin:0">انقر على طبقةٍ في الرسم أو في القائمة لعرض عمقها وحالتها وحرارتها وتركيبها.</p>
        </div>
      </div>
    </div>
    <p class="callout" style="margin-top:1rem">
      <b>لماذا لا نحفر وننظر؟</b> أعمق حفرةٍ بشريةٍ في التاريخ (بئر كولا فائقة العمق) بلغت نحو
      <span class="n">12.2</span> كم فقط — أي أقل من <span class="n">0.2%</span> من نصف قطر الأرض.
      فمعرفتنا بالداخل كلها تقريباً <span class="hl">معرفةٌ غير مباشرة</span>، مصدرها الزلازل (الشريحة ٨).
    </p>
  </section>

  <!-- ═══════════ 3 · القشرة ═══════════ -->
  <section class="slide" role="group" aria-label="القشرة الأرضية">
    <p class="eyebrow">الشريحة ٣ · القشرة</p>
    <h2>القشرة الأرضية: غلافٌ رقيقٌ غيرُ متجانس</h2>
    <div class="grid g-2">
      <div>
        <p>القشرة هي الطبقة الصخرية الصلبة التي نعيش عليها، وهي <strong>الأرقّ والأبرد</strong> بين الطبقات الأربع —
          لكنها ليست نوعاً واحداً.</p>
        <ul class="tick">
          <li><strong>القشرة القارية:</strong> سماكتها <span class="n">30–50</span> كم، وقد تصل إلى نحو <span class="n">70</span> كم
            تحت الهضاب الجبلية العريضة. تركيبتها غرانيتيةٌ غنيةٌ بالسيليكون والألمنيوم، وكثافتها نحو <span class="n">2.7</span> غ/سم³.</li>
          <li><strong>القشرة المحيطية:</strong> أرقّ بكثير (<span class="n">5–10</span> كم)، لكنها أعلى كثافةً
            (<span class="n">≈ 3.0</span> غ/سم³) لأن تركيبها بازلتٌ غنيٌّ بالسيليكون والمغنيسيوم.</li>
          <li><strong>الفرق في العمر مذهل:</strong> لا يتجاوز عمر أقدم القشرة المحيطية نحو
            <span class="n">200</span> مليون سنة، لأن صفائح القاع تُعاد تدويرها باستمرار؛ أما صخور القشرة القارية فبعضها يقترب من
            <span class="n">4</span> مليارات سنة.</li>
          <li><strong>الحدّ الفاصل:</strong> يُعرف بـ<span class="hl">فواصل موهو</span> (انقطاع موهويفيتش)،
            وهو العمق الذي تقفز عنده سرعة الموجات الزلزالية فجأةً لأن الصخور تحت القشرة مختلفة التركيب.</li>
        </ul>
        <p class="lede" style="font-size:.86rem">أكثر العناصر وفرةً في القشرة (نسبٌ كتليةٍ تقريبية):
