          <circle cx="250" cy="200" r="87.42" fill="none" stroke="rgba(255,255,255,.5)" stroke-width="1.3"/>
          <circle cx="250" cy="200" r="30.66" fill="none" stroke="rgba(255,255,255,.6)" stroke-width="1.1"/>
          <circle cx="250" cy="200" r="160" fill="none" stroke="rgba(255,255,255,.5)" stroke-width="1.4"/>
