<script>
(function () {
  'use strict';
  var root = document.documentElement;
  var slides = Array.prototype.slice.call(document.querySelectorAll('.slide'));
  var KEY = 'earth-deck-v1';
  var i = 0;

  /* ---------- dots ---------- */
  var dots = document.getElementById('dots');
  slides.forEach(function (s, idx) {
    var b = document.createElement('button');
    b.type = 'button';
    b.setAttribute('role', 'tab');
    b.setAttribute('aria-label', 'الشريحة ' + (idx + 1));
    b.addEventListener('click', function () { go(idx); });
    dots.appendChild(b);
  });
  var dotEls = Array.prototype.slice.call(dots.children);

  /* ---------- navigation ---------- */
  function go(n) {
    i = Math.max(0, Math.min(slides.length - 1, n));
    slides.forEach(function (s, idx) { s.hidden = idx !== i; });
    dotEls.forEach(function (d, idx) {
      if (idx === i) d.setAttribute('aria-current', 'true');
      else d.removeAttribute('aria-current');
    });
    document.getElementById('counter').textContent = 'شريحة ' + (i + 1) + ' من ' + slides.length;
    document.getElementById('progress').style.width =
      (slides.length > 1 ? (i / (slides.length - 1)) * 100 : 100) + '%';
    var p = document.getElementById('prev'), n2 = document.getElementById('next');
    var p2 = document.getElementById('prev2'), n3 = document.getElementById('next2');
    p.disabled = n2.disabled = p2.disabled = n3.disabled = (i === 0 || i === slides.length - 1)
      ? false : false;
    p.disabled = p2.disabled = (i === 0);
    n2.disabled = n3.disabled = (i === slides.length - 1);
    try { localStorage.setItem(KEY, String(i)); } catch (e) {}
    if (history.replaceState) history.replaceState(null, '', '#' + (i + 1));
    window.scrollTo(0, 0);
  }
  function next() { go(i + 1); }
  function prev() { go(i - 1); }

  ['next', 'next2'].forEach(function (id) {
    document.getElementById(id).addEventListener('click', next);
  });
  ['prev', 'prev2'].forEach(function (id) {
    document.getElementById(id).addEventListener('click', prev);
  });

  /* keyboard: forward is Left in RTL, backward is Right */
  document.addEventListener('keydown', function (e) {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    var t = e.target;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
    switch (e.key) {
      case 'ArrowLeft': case 'PageDown': e.preventDefault(); next(); break;
      case 'ArrowRight': case 'PageUp': e.preventDefault(); prev(); break;
      case ' ': e.preventDefault(); next(); break;
      case 'Home': e.preventDefault(); go(0); break;
      case 'End': e.preventDefault(); go(slides.length - 1); break;
      case 'f': case 'F': toggleFS(); break;
      case 'p': case 'P': e.preventDefault(); window.print(); break;
      default:
        if (/^[1-9]$/.test(e.key)) go(parseInt(e.key, 10) - 1);
    }
  });

  /* touch swipe (RTL-aware) */
  var x0 = null, y0 = null;
  window.addEventListener('touchstart', function (e) {
    x0 = e.touches[0].clientX; y0 = e.touches[0].clientY;
  }, { passive: true });
  window.addEventListener('touchend', function (e) {
    if (x0 === null) return;
    var dx = e.changedTouches[0].clientX - x0;
    var dy = e.changedTouches[0].clientY - y0;
    if (Math.abs(dx) > 55 && Math.abs(dx) > Math.abs(dy) * 1.5) { dx < 0 ? next() : prev(); }
    x0 = y0 = null;
  }, { passive: true });

  /* ---------- interactive layer panel ---------- */
  var LAYERS = {
    crust: { name: 'القشرة الأرضية', color: 'var(--crust)',
      rows: [['الامتداد', 'من السطح إلى ≈ 35 كم (تصل إلى 70 كم تحت الجبال)'],
             ['الحالة', 'صلبة، هشة، مكسّرة إلى صفائح'],
             ['الحرارة', 'أقل من 200 °م قرب السطح حتى ≈ 1000 °م عند القاعدة'],
             ['الكثافة', '2.7 (قارية) – 3.0 (محيطية) غ/سم³'],
             ['التركيب', 'سيليكات: أكسجين، سيليكون، ألمنيوم، حديد'],
             ['ملاحظة', 'القشرة المحيطية فتية (≈ 200 مليون سنة) والقارية قديمة (حتى ≈ 4 مليارات سنة)']] },
    mantle: { name: 'الوشاح', color: 'var(--mantle)',
      rows: [['الامتداد', 'من ≈ 35 كم إلى 2890 كم — سماكة ≈ 2890 كم'],
             ['الحالة', 'صلبة شديدة اللزوجة؛ تنساب سنتيمترات في السنة'],
             ['الحرارة', '≈ 1000 °م عند القمة إلى ≈ 3700 °م عند القاعدة'],
             ['الكثافة', '3.3 – 5.5 غ/سم³'],
             ['التركيب', 'سيليكات غنية بالحديد والمغنيسيوم (أوليفين، بيروكسين)'],
             ['الدور', 'تيارات الحمل فيه هي محرّك الصفائح التكتونية'],
             ['الحصة', '≈ 82% من حجم الأرض و 67% من كتلتها']] },
    outer: { name: 'اللب الخارجي', color: 'var(--outer)',
      rows: [['الامتداد', 'من 2890 كم إلى 5150 كم — سماكة ≈ 2260 كم'],
             ['الحالة', 'سائلة — أكبر كتلة سائلة في الكوكب'],
             ['الحرارة', '4000 – 5000 °م'],
             ['الكثافة', '9.9 – 12.2 غ/سم³'],
             ['التركيب', 'حديد ونيكل + عناصر خفيفة (كبريت، أكسجين، سيليكون، كربون)'],
             ['الدور', 'الدينامو الأرضي: يولّد المجال المغناطيسي'],
             ['الدليل', 'موجات S تتوقف هنا تماماً (غوتنبرغ، 1914)']] },
    inner: { name: 'اللب الداخلي', color: 'var(--inner)',
      rows: [['الامتداد', 'من 5150 كم إلى المركز عند 6371 كم'],
             ['نصف القطر', '≈ 1221 كم'],
             ['الحالة', 'صلبة رغم الحرارة، بسبب الضغط الهائل'],
             ['الحرارة', '5200 – 5400 °م ≈ حرارة سطح الشمس'],
             ['الضغط', '≈ 330 – 360 غيغاباسكال'],
             ['الكثافة', '≈ 12.8 – 13.0 غ/سم³'],
             ['الاكتشاف', 'إنجي ليمان، 1936، من موجات P داخل منطقة الظل']] }
  };
  var panel = document.getElementById('panel');

  function select(key) {
    var d = LAYERS[key];
    if (!d) return;
    var html = '<h3><span class="sw" style="display:inline-block;width:.8rem;height:.8rem;'
             + 'border-radius:3px;background:' + d.color + ';margin-inline-end:.45rem"></span>'
             + d.name + '</h3><dl>';
    d.rows.forEach(function (r) {
      html += '<dt>' + r[0] + '</dt><dd>' + r[1] + '</dd>';
    });
    html += '</dl>';
    panel.innerHTML = html;
    document.querySelectorAll('.legend button').forEach(function (b) {
      b.setAttribute('aria-pressed', String(b.dataset.layer === key));
    });
    document.querySelectorAll('.lyr').forEach(function (c) {
      if (c.dataset.layer === key) c.classList.add('is-sel');
      else c.classList.remove('is-sel');
    });
  }
  document.querySelectorAll('.legend button').forEach(function (b) {
    b.addEventListener('click', function () { select(b.dataset.layer); });
  });
  document.querySelectorAll('.lyr').forEach(function (c) {
    c.addEventListener('click', function () { select(c.dataset.layer); });
    c.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(c.dataset.layer); }
    });
  });
  select('mantle');

  /* ---------- misc toolbar ---------- */
  function toggleFS() {
    var d = document;
    if (!d.fullscreenElement) {
      if (root.requestFullscreen) root.requestFullscreen().catch(function () {});
    } else if (d.exitFullscreen) d.exitFullscreen();
  }
  document.getElementById('fs').addEventListener('click', toggleFS);
  document.getElementById('print').addEventListener('click', function () { window.print(); });

