import sys

def strip(src: str) -> str:
    out = []
    i, n = 0, len(src)
    NORMAL, LINE, BLOCK, STR = 0, 1, 2, 3
    state = NORMAL
    depth = 0
    ws_buf = []          # whitespace pending emission (dropped if a comment starts)
    while i < n:
        c = src[i]
        if state == NORMAL:
            two = src[i:i+2]
            if two == '//':
                state = LINE; ws_buf = []; i += 2; continue
            if two == '/*':
                state = BLOCK; depth = 1; ws_buf = []; i += 2; continue
            if c == '"':
                if ws_buf: out.extend(ws_buf); ws_buf = []
                state = STR; out.append(c); i += 1; continue
            if c in ' \t\r':
                ws_buf.append(c); i += 1; continue
            if ws_buf:
                out.extend(ws_buf); ws_buf = []
            out.append(c); i += 1; continue
        if state == STR:
            out.append(c)
            if c == '\\' and i + 1 < n:      # keep escape + escaped char verbatim
                out.append(src[i+1]); i += 2; continue
            if c == '"':
                state = NORMAL
            i += 1; continue
        if state == LINE:
            if c == '\n':
                state = NORMAL; out.append(c)
            i += 1; continue
        if state == BLOCK:
            two = src[i:i+2]
            if two == '/*':
                depth += 1; i += 2; continue
            if two == '*/':
                depth -= 1; i += 2
                if depth == 0: state = NORMAL
                continue
            if c == '\n':
                out.append(c)                 # preserve line structure
            i += 1; continue
    return ''.join(out)

